<?php declare(strict_types=1);require_once dirname(__DIR__).'/_bootstrap.php';apiMethod('POST','PUT');apiCsrf();$uid=apiAuth(['supplier']);$in=apiInput();$id=apiId($in['id']??0);$price=$in['price']??null;if(!is_numeric($price)||$price<0)apiError('Invalid price',422);$s=apiDb()->prepare('UPDATE quotation_requests q JOIN suppliers s ON s.id=q.supplier_id SET q.status="responded",q.quoted_price=? WHERE q.id=? AND s.user_id=?');$s->execute([$price,$id,$uid]);if(!$s->rowCount())apiError('Quotation not found',404);apiResponse(['id'=>$id,'status'=>'responded']);